package com.sam.syncstation;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import androidx.core.view.WindowCompat;import java.util.Locale;
public class MainActivity extends Activity {
 LinearLayout content; TextView pulse; final int bg=Color.rgb(10,13,20),panel=Color.rgb(23,29,41),accent=Color.rgb(255,112,92);
 public void onCreate(Bundle b){super.onCreate(b);WindowCompat.setDecorFitsSystemWindows(getWindow(),true);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);
 ScrollView s=new ScrollView(this);s.setBackgroundColor(bg);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(22),dp(20),dp(30));s.addView(content);setContentView(s);
 content.addView(txt("SYNC / DEVICE SYSTEM",12,accent));TextView title=txt("Sync Station",30,Color.WHITE);title.setPadding(0,dp(6),0,dp(4));content.addView(title);content.addView(txt("Your device, understood.",15,0xffa5b1c4));
 LinearLayout hero=card();hero.addView(txt("DEVICE PULSE",11,accent));pulse=txt("Reading device pulse…",15,Color.WHITE);hero.addView(pulse);Button refresh=btn("Refresh device pulse");refresh.setOnClickListener(v->refreshPulse());hero.addView(refresh);content.addView(hero);
 addModule("Pocket Automator","Visual trigger → condition → action planning. No automations execute yet.","Automation sandbox");
 addModule("SoundCanvas","Audio-reactive visual concept; native DreamService registration is a later spike.","SoundCanvas preview");
 addModule("Screen Tools","Detached-feel pointer sandbox. Cross-app touch injection is not claimed.","Pointer sandbox");
 addModule("Device Playground","Opt-in diagnostics for touch, display, audio, vibration, sensors, camera and flash.","Diagnostic plan");
 addModule("Capability Center","Permission and Android-capability checklist before features are enabled.","Capability checklist");refreshPulse();}
 void addModule(String n,String d,String a){LinearLayout c=card();c.addView(txt(n,19,Color.WHITE));TextView detail=txt(d,14,0xffadb7c7);detail.setPadding(0,dp(7),0,dp(10));c.addView(detail);Button b=btn(a);b.setOnClickListener(v->showModule(n));c.addView(b);content.addView(c);}
 void showModule(String n){content.removeViews(1,Math.max(0,content.getChildCount()-1));content.addView(txt(n,26,Color.WHITE));if(n.equals("Screen Tools")){content.addView(txt("Drag inside this test area to move the cursor. This is an in-app interaction prototype, not arbitrary touch injection into other apps.",14,Color.LTGRAY));PointerPad pad=new PointerPad(this);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(320));p.topMargin=dp(14);content.addView(pad,p);}else content.addView(txt(desc(n),15,Color.LTGRAY));Button back=btn("← Back to Station");back.setOnClickListener(v->recreate());content.addView(back);}
 String desc(String n){if(n.equals("Pocket Automator"))return "Capability-first planning. Background execution, Accessibility, Shizuku and Android restrictions need validation before enabling actions.";if(n.equals("SoundCanvas"))return "Next spike: implement a native DreamService and check whether Android lists Sync Station as a selectable screensaver. Other apps' audio capture is a separate restriction.";if(n.equals("Device Playground"))return "Next: implement each test with clear instructions, opt-in permissions and honest hardware/API support reporting.";return "Next: show each feature's permission, API support, privacy implications and enable/disable controls.";}
 void refreshPulse(){Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int l=b==null?-1:b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),sc=b==null?100:b.getIntExtra(BatteryManager.EXTRA_SCALE,100);int pct=l<0?-1:Math.round(l*100f/Math.max(1,sc));int st=b==null?-1:b.getIntExtra(BatteryManager.EXTRA_STATUS,-1);String charging=(st==BatteryManager.BATTERY_STATUS_CHARGING||st==BatteryManager.BATTERY_STATUS_FULL)?"Charging":"Not charging";StatFs fs=new StatFs(Environment.getDataDirectory().getAbsolutePath());ActivityManager.MemoryInfo mi=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(mi);pulse.setText((pct<0?"Battery unavailable":pct+"% battery")+" • "+charging+"\nStorage free: "+fmt(fs.getAvailableBytes())+" / "+fmt(fs.getTotalBytes())+"\nSystem memory available: "+fmt(mi.availMem)+(mi.lowMemory?" • low-memory signal":""));}
 String fmt(long n){return String.format(Locale.US,"%.1f GB",n/1073741824.0);} LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),dp(16),dp(16),dp(16));l.setBackgroundColor(panel);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(14);l.setLayoutParams(p);return l;}
 TextView txt(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}
 class PointerPad extends View{Paint p=new Paint(3);float x,y;boolean init;PointerPad(Context c){super(c);setBackgroundColor(0xff101621);}protected void onDraw(Canvas c){super.onDraw(c);if(!init){x=getWidth()/2f;y=getHeight()/2f;init=true;}p.setColor(0xff435066);p.setStrokeWidth(dp(1));for(int i=1;i<5;i++)c.drawLine(0,getHeight()*i/5f,getWidth(),getHeight()*i/5f,p);p.setColor(accent);p.setStrokeWidth(dp(2));c.drawCircle(x,y,dp(13),p);c.drawLine(x-dp(22),y,x+dp(22),y,p);c.drawLine(x,y-dp(22),x,y+dp(22),p);}public boolean onTouchEvent(android.view.MotionEvent e){x=Math.max(0,Math.min(getWidth(),e.getX()));y=Math.max(0,Math.min(getHeight(),e.getY()));invalidate();return true;}}
}